                    p((free) + 1) = ((-(((n((ia) + 1) * p((ia) + 1)) + (n((ib) + 1) * p((ib) + 1))))) / n((free) + 1));
                    if (asils.pc.fabs(p((free) + 1)) <= (hx((free) + 1) + 1e-12))
                        px((np) + 1) = p(1);
                        py((np) + 1) = p(2);
                        pz((np) + 1) = p(3);
                        np = (np + 1);
                    end
                end
            end
        end
    end
    t = [0; 1; 0];
    if (asils.pc.fabs(n(1)) < 0.9)
        t = [1; 0; 0];
    end
    tn = (((t(1) * n(1)) + (t(2) * n(2))) + (t(3) * n(3)));
    w = [(t(1) - (n(1) * tn)); (t(2) - (n(2) * tn)); (t(3) - (n(3) * tn))];
    wn = asils.pc.norm_(w);
    u = zeros(3, 1);
    if (~(wn < 1e-300))
        rw = (1 / wn);
        u = [(w(1) * rw); (w(2) * rw); (w(3) * rw)];
    end
    v = [((n(2) * u(3)) - (n(3) * u(2))); ((n(3) * u(1)) - (n(1) * u(3))); ((n(1) * u(2)) - (n(2) * u(1)))];
    qx = zeros(12, 1);
    qy = zeros(12, 1);
    ang = zeros(12, 1);
    for i = (0):((12) - 1)
        ang((i) + 1) = Inf;
    end
    for i = (0):((np) - 1)
        qx((i) + 1) = (((px((i) + 1) * u(1)) + (py((i) + 1) * u(2))) + (pz((i) + 1) * u(3)));
        qy((i) + 1) = (((px((i) + 1) * v(1)) + (py((i) + 1) * v(2))) + (pz((i) + 1) * v(3)));
        ang((i) + 1) = atan2(qy((i) + 1), qx((i) + 1));
    end
    ord = asils.pc.argsort_(ang);
    sx = zeros(12, 1);
    sy = zeros(12, 1);
    m = 0;
    for i = (0):((np) - 1)
        j = ord((i) + 1);
        if ((m == 0) || (~((asils.pc.fabs((qx((j) + 1) - sx(((m - 1)) + 1))) < 1e-12) && (asils.pc.fabs((qy((j) + 1) - sy(((m - 1)) + 1))) < 1e-12))))
            sx((m) + 1) = qx((j) + 1);
            sy((m) + 1) = qy((j) + 1);
            m = (m + 1);
        end
    end
    area = 0;
    perim = 0;
    for i = (0):((m) - 1)
        k = rem((i + 1), m);
        area = (area + ((sx((i) + 1) * sy((k) + 1)) - (sx((k) + 1) * sy((i) + 1))));
        perim = (perim + sqrt((asils.pc.ipow((sx((k) + 1) - sx((i) + 1)), 2) + asils.pc.ipow((sy((k) + 1) - sy((i) + 1)), 2))));
